from pathlib import Path
root=Path('/home/tritlo/Code/mcfta/lean/MicroCFTA')
out=Path('/tmp/mcfta-prepared-composition-20261028/sibling-origins')
s=(root/'SourcePruningEnumerationPreparedFiniteSiblingCoverage.lean').read_text()
s=s.replace('import MicroCFTA.SourcePruningEnumerationPreparedFiniteHeadCoverage','import MicroCFTA.SourcePruningEnumerationPreparedFiniteHeadOrigins',1)
s=s.replace('# Coverage of an indexed prepared finite recursive sibling scan','# Original subtree paths at an indexed prepared sibling event',1)
s=s.replace('new worker, its own finite contract and its new failure type.','new worker, its own finite contract and its new failure type.\nThe chosen accepting event constructs one model extension with original paths\nfor every variable in its actual callback-entry cache. Earlier hook stops\nremain an explicit alternative. No model after that hook is assumed.',1)
s=s.replace('open EnumerationState EnumerationCorrectness EnumerationSchedule InternedConstructorTemplates InternedProbeProvenance','open EnumerationState EnumerationCorrectness EnumerationSchedule InternedConstructorTemplates InternedProbeProvenance\nopen SourcePruningEnumerationOrigins',1)
s=s.replace('theorem alternatives_finite_complete_resources_accepting\n','theorem alternatives_finite_complete_resources_origins\n',1)
s=s.replace('(ambient : InternedGuardedLanguage.Env Symbol) (assignment : Nat → Language.Term Symbol),','(ambient : InternedGuardedLanguage.Env Symbol) (assignment : Nat → Language.Term Symbol)\n            (whole : Language.Term Symbol),',1)
s=s.replace('ambient chosen (assignment uv) →\n            ∃','ambient chosen (assignment uv) →\n            AssignmentOrigins whole before.core.counter assignment →\n            ∃',1)
s=s.replace('extended afterCache.core) ∨','extended afterCache.core ∧\n                    AssignmentOrigins whole afterCache.core.counter extended) ∨',1)
s=s.replace('headResources, headAccepting⟩ :=','headResources, headOrigins⟩ :=',1)
s=s.replace('SourcePruningEnumerationPreparedNativeHookResources.head_finite_complete_resources_accepting','SourcePruningEnumerationPreparedNativeHookResources.head_finite_complete_resources_origins',1)
s=s.replace('intro index chosen found supported ambient assignment satisfied accepted','intro index chosen found supported ambient assignment whole satisfied accepted origins')
s=s.replace('impossible, _filled, _final⟩ :=\n                headAccepting ambient assignment satisfied accepted','impossible, _filled, _final, _origins⟩ :=\n                headOrigins ambient assignment whole satisfied accepted origins',1)
s=s.replace('completed, filled, afterSatisfied⟩ :=\n                    headAccepting ambient assignment satisfied accepted','completed, filled, afterSatisfied, afterOrigins⟩ :=\n                    headOrigins ambient assignment whole satisfied accepted origins',1)
s=s.replace('.inl ⟨rfl, rfl, extended, agree, originalSatisfied, filled, afterSatisfied⟩⟩','.inl ⟨rfl, rfl, extended, agree, originalSatisfied, filled, afterSatisfied, afterOrigins⟩⟩',1)
s=s.replace('ambient assignment middleSatisfied accepted\n','ambient assignment whole middleSatisfied accepted origins\n',1)
s=s.replace('⟨sameIndex, sameEdge, extended, agree, oldSatisfied, filled, afterSatisfied⟩ |','⟨sameIndex, sameEdge, extended, agree, oldSatisfied, filled, afterSatisfied, afterOrigins⟩ |',1)
s=s.replace('.inl ⟨by omega, sameEdge, extended, agree, originalSatisfied, filled, afterSatisfied⟩','.inl ⟨by omega, sameEdge, extended, agree, originalSatisfied, filled, afterSatisfied, afterOrigins⟩',1)
s=s.replace('completed, filled, afterSatisfied⟩ := headAccepting ambient assignment satisfied accepted','completed, filled, afterSatisfied, afterOrigins⟩ :=\n                    headOrigins ambient assignment whole satisfied accepted origins',1)
s=s.replace('extended, agree, originalSatisfied, filled, by\n                    simpa only [actualSame.1] using afterSatisfied⟩','extended, agree, originalSatisfied, filled, (by\n                    simpa only [actualSame.1] using afterSatisfied), afterOrigins⟩',1)
assert 'headAccepting' not in s
p=out/'drafts/v1/SourcePruningEnumerationPreparedFiniteSiblingOrigins.lean';p.write_text(s)
